import { types } from "node:util";
import * as direct from "node:util/types";
import * as namespace from "./namespace.js";

export function reportTypes() {
  const probes = Object.keys(types).filter((name) => !["isCryptoKey", "isKeyObject", "isExternal"].includes(name)).sort();
  const values = [
    ["undefined", undefined], ["null", null], ["number", 1], ["string", "x"], ["boolean", true], ["symbol", Symbol("x")], ["bigint", 1n],
    ["array", []], ["object", {}], ["function", function () {}], ["bound", (async function () {}).bind(null)],
    ["async", async function () {}], ["generator-function", function* () {}], ["async-generator-function", async function* () {}],
    ["generator", (function* () {})()], ["async-generator", (async function* () {})()],
    ["arguments", (function () { return arguments; })(1)], ["sloppy-arguments", Function("a", "return arguments")(1)],
    ["date", new Date(0)], ["invalid-date", new Date(NaN)], ["regexp", /abc/g], ["error", new Error("bad")], ["type-error", new TypeError("bad")],
    ["error-subclass", new (class extends Error {})()], ["aggregate-error", new AggregateError([], "bad")],
    ["promise", Promise.resolve(1)], ["promise-subclass", new (class extends Promise {})(resolve => resolve(1))], ["thenable", { then() {} }],
    ["map", new Map()], ["set", new Set()], ["weakmap", new WeakMap()], ["weakset", new WeakSet()],
    ["map-iterator", new Map().entries()], ["set-iterator", new Set().values()], ["array-iterator", [][Symbol.iterator]()],
    ["number-object", Object(1)], ["string-object", Object("x")], ["boolean-object", Object(true)], ["symbol-object", Object(Symbol("x"))], ["bigint-object", Object(1n)],
    ["buffer", Buffer.alloc(0)], ["arraybuffer", new ArrayBuffer(0)], ["sharedbuffer", new SharedArrayBuffer(0)], ["dataview", new DataView(new ArrayBuffer(0))],
    ["namespace", namespace], ["namespace-proxy", new Proxy(namespace, {})],
  ];
  for (const ctor of [Uint8Array, Uint8ClampedArray, Uint16Array, Uint32Array, Int8Array, Int16Array, Int32Array, Float16Array, Float32Array, Float64Array, BigInt64Array, BigUint64Array]) {
    values.push([ctor.name, new ctor(0)], [ctor.name + "-subclass", new (class extends ctor {})(0)]);
  }
  let reads = 0;
  const throwing = { get [Symbol.toStringTag]() { reads++; throw new Error("tag read"); } };
  values.push(["throwing-tag", throwing]);
  for (const [label, value] of [...values]) {
    if (value === null || (typeof value !== "object" && typeof value !== "function")) continue;
    if (label === "throwing-tag" || label === "namespace" || label === "namespace-proxy") continue;
    values.push([label + "-proxy", new Proxy(value, { get() { throw new Error("get trap"); }, getPrototypeOf() { throw new Error("prototype trap"); } })]);
    // A prototype cannot manufacture an internal brand.
    values.push([label + "-fake-prototype", Object.create(Object.getPrototypeOf(value))]);
    if (Object.isExtensible(value)) Object.defineProperty(value, Symbol.toStringTag, { value: "Fake", configurable: true });
  }
  for (const tag of ["ArrayBuffer", "SharedArrayBuffer", "Uint8Array", "DataView", "Arguments", "Generator", "AsyncGenerator", "Map Iterator", "Set Iterator", "Module", "Error", "Promise", "RegExp"]) {
    values.push(["spoof-" + tag, { [Symbol.toStringTag]: tag }]);
  }
  const revocable = Proxy.revocable({}, {}); revocable.revoke(); values.push(["revoked", revocable.proxy]);
  console.log("aliases", probes.every(name => types[name] === direct[name]), probes.join(","));
  for (const [label, value] of values) console.log(label, probes.map(name => types[name](value) ? name : "").filter(Boolean).join(","));
  console.log("tag-reads", reads);
  console.log("missing", probes.map(name => types[name]()).join(","));
  let events = "";
  console.log("surplus", types.isMap((events += "first,", new Map()), (events += "second,", 1)), events);
  console.log("shape", probes.map(name => name + ":" + types[name].name + ":" + types[name].length).join(","));
  console.log("view-alias", types.isArrayBufferView === ArrayBuffer.isView);
}

export function reportNativeTypes(probe) {
  const values = [new Uint8Array(0), new DataView(new ArrayBuffer(0)), new ArrayBuffer(0), new Map(), new Set(), new WeakMap(), new WeakSet(),
    /abc/g, new TypeError("bad"), Promise.resolve(1), async function () {}, function* () {}, (function* () {})(), new Proxy({}, {})];
  for (const value of values) console.log("native-boundary", probe(value));
}
